# RRHH Custodia Gate3B - bounded SQL preflight.
# El caller nunca suministra SQL.
def _rrhh_custodia_gate3b_sql_preflight_builder(request):
    context = _g3_context(request)
    if context != "RRHH_CUSTODIA":
        raise SemanticCapabilityError(
            "SEMANTIC_BOUNDED_CONTEXT_UNSUPPORTED"
        )

    constraints = request.get("constraints")
    if constraints is not None and (
        not isinstance(constraints, Mapping)
        or bool(constraints)
    ):
        raise SemanticCapabilityError(
            "SEMANTIC_CONSTRAINTS_UNSUPPORTED"
        )

    queries = [
        {"name": "custodia_target_table_collisions", "sql": "SELECT s.name AS schema_name, t.name AS table_name FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name='dbo' AND t.name IN ('Custodia_Recurso','Custodia_Resguardo','Custodia_Movimiento','Custodia_Devolucion','Custodia_Incidencia','Custodia_CargoPropuesto','RH_UniformePolitica','RH_UniformePoliticaDetalle') ORDER BY t.name"},
        {"name": "custodia_constraint_name_collisions", "sql": "SELECT o.type_desc, o.name, OBJECT_SCHEMA_NAME(o.parent_object_id) AS parent_schema, OBJECT_NAME(o.parent_object_id) AS parent_object FROM sys.objects o WHERE o.name LIKE '%Custodia%' OR o.name LIKE '%UniformePolitica%' ORDER BY o.name"},
        {"name": "custodia_index_name_collisions", "sql": "SELECT OBJECT_SCHEMA_NAME(i.object_id) AS schema_name, OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name FROM sys.indexes i WHERE i.name LIKE '%Custodia%' OR i.name LIKE '%Uniforme%' ORDER BY i.name"},
        {"name": "custodia_fk_target_types", "sql": "SELECT s.name AS schema_name,t.name AS table_name,c.name AS column_name,ty.name AS data_type,c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE s.name='dbo' AND ((t.name='RH_Colaboradores_Expediente' AND c.name='ColaboradorID') OR (t.name='RH_Cat_Puestos' AND c.name='PuestoID') OR (t.name='Producto_Catalogo' AND c.name='ProductoID') OR (t.name='ActivoFijo_Activos' AND c.name='ActivoID') OR (t.name='Sistema_Empresas' AND c.name='EmpresaID') OR (t.name='Unidades_Negocio' AND c.name='id') OR (t.name='Sistema_Sucursales' AND c.name='SucursalID') OR (t.name='Usuario_Catalogo' AND c.name='UsuarioID') OR (t.name='Gobierno_Documento' AND c.name='DocumentoID') OR (t.name='RH_Nomina_Detalle' AND c.name='NominaDetalleID')) ORDER BY t.name,c.name"},
        {"name": "custodia_fk_targets_keys", "sql": "SELECT s.name AS schema_name,t.name AS table_name,c.name AS column_name,i.name AS index_name,i.is_unique FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.indexes i ON i.object_id=t.object_id JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=t.object_id AND c.column_id=ic.column_id WHERE s.name='dbo' AND i.is_unique=1 AND ((t.name='RH_Colaboradores_Expediente' AND c.name='ColaboradorID') OR (t.name='RH_Cat_Puestos' AND c.name='PuestoID') OR (t.name='Producto_Catalogo' AND c.name='ProductoID') OR (t.name='ActivoFijo_Activos' AND c.name='ActivoID') OR (t.name='Sistema_Empresas' AND c.name='EmpresaID') OR (t.name='Unidades_Negocio' AND c.name='id') OR (t.name='Sistema_Sucursales' AND c.name='SucursalID') OR (t.name='Usuario_Catalogo' AND c.name='UsuarioID') OR (t.name='Gobierno_Documento' AND c.name='DocumentoID') OR (t.name='RH_Nomina_Detalle' AND c.name='NominaDetalleID')) ORDER BY t.name,c.name"},
        {"name": "custodia_ddl_permissions_observed", "sql": "SELECT DB_NAME() AS database_name, ORIGINAL_LOGIN() AS original_login, SUSER_SNAME() AS effective_login, HAS_PERMS_BY_NAME(DB_NAME(),'DATABASE','CREATE TABLE') AS can_create_table, HAS_PERMS_BY_NAME('dbo','SCHEMA','ALTER') AS can_alter_dbo, HAS_PERMS_BY_NAME(DB_NAME(),'DATABASE','VIEW DEFINITION') AS can_view_definition"},
        {"name": "custodia_scope_columns_presence", "sql": "SELECT t.name AS table_name,c.name AS column_name,ty.name AS data_type,c.is_nullable FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE s.name='dbo' AND ((t.name='Sistema_Empresas' AND c.name='EmpresaID') OR (t.name='Unidades_Negocio' AND c.name='id') OR (t.name='Sistema_Sucursales' AND c.name='SucursalID')) ORDER BY t.name"},
    ]

    return {
        "actions": [],
        "checks": [{
            "type": "sql_readonly_audit",
            "queries": queries,
        }],
        "scheduling": _g3_scheduling(context),
    }


register_capability(
    SemanticCapability(
        code="RRHH_CUSTODIA_GATE3B_SQL_PREFLIGHT",
        modes=("READ_ONLY",),
        builder=_rrhh_custodia_gate3b_sql_preflight_builder,
    )
)
